function statusTarefaDefaults(){
  return [
    {id:"nao_iniciada",nome:"N\u00e3o iniciada",cor:"#94a3b8",ordem:0,finalizador:false,ativo:true},
    {id:"pendente",nome:"Pendente",cor:"#e2445c",ordem:1,finalizador:false,ativo:true},
    {id:"em_andamento",nome:"Em andamento",cor:"#2b76e5",ordem:2,finalizador:false,ativo:true},
    {id:"pausado",nome:"Pausado",cor:"#fdab3d",ordem:3,finalizador:false,ativo:true},
    {id:"bloqueada",nome:"Cancelada",cor:"#626f86",ordem:4,finalizador:true,ativo:true},
    {id:"concluido",nome:"Conclu\u00edda",cor:"#00c875",ordem:5,finalizador:true,ativo:true},
    {id:"concluida",nome:"Conclu\u00edda",cor:"#16a34a",ordem:6,finalizador:true,ativo:false}
  ];
}
function statusTarefaList(includeInactive){
  var rows=(tarefaStatusDB&&tarefaStatusDB.length?tarefaStatusDB:statusTarefaDefaults()).slice();
  if(!includeInactive)rows=rows.filter(function(s){return s.ativo!==false;});
  rows.sort(function(a,b){return (a.ordem||0)-(b.ordem||0);});
  return rows;
}
function statusTarefaById(id,includeInactive){
  var rows=statusTarefaList(!!includeInactive);
  return rows.find(function(s){return s.id===id;})||statusTarefaDefaults().find(function(s){return s.id===id;})||null;
}
function statusTarefaLabel(id){
  var st=statusTarefaById(id,true);
  return st?(st.nome||st.id):(id||"Pendente");
}
function statusTarefaCor(id,fallback){
  var st=statusTarefaById(id,true);
  return st&&st.cor?st.cor:(fallback||"#94a3b8");
}
function statusTarefaFinalizador(id){
  var st=statusTarefaById(id,true);
  return !!(st&&st.finalizador)||id==="concluido"||id==="concluida";
}
// Cancelada: encerra a subtarefa (sai de alertas e pendencias), mas nao conta como feita no progresso
function statusTarefaCancelado(id){
  if(id==="cancelada")return true;
  var st=statusTarefaById(id,true);
  return !!(st&&/^cancel/i.test(st.nome||""));
}
function statusTarefaFeita(id){return statusTarefaFinalizador(id)&&!statusTarefaCancelado(id);}
function statusTarefaProgresso(lista){
  var validas=(lista||[]).filter(function(t){return !statusTarefaCancelado(t.status);});
  return {feitas:validas.filter(function(t){return statusTarefaFinalizador(t.status);}).length,total:validas.length};
}
// Responsaveis: lista em "responsaveis"; "responsavel" guarda o primeiro (compatibilidade e RLS)
function respsDe(o){
  if(!o)return [];
  if(Array.isArray(o.responsaveis)&&o.responsaveis.length)return o.responsaveis.filter(Boolean);
  return o.responsavel?[o.responsavel]:[];
}
function setResps(o,lista){
  var u=[];(lista||[]).forEach(function(r){if(r&&u.indexOf(r)<0)u.push(r);});
  o.responsaveis=u;o.responsavel=u[0]||"";
  return o;
}
function statusTarefaDataHoje(){
  return new Date().toISOString().slice(0,10);
}
function statusTarefaCamposConclusao(item,status){
  var campos=Object.assign({},item&&item.campos_valores?item.campos_valores:{});
  if(statusTarefaFeita(status)){
    if(!campos.concluida_em)campos.concluida_em=statusTarefaDataHoje();
  } else {
    delete campos.concluida_em;
  }
  return campos;
}
function normalizarStatusTarefa(item,status){
  var out=Object.assign({},item||{});
  var st=status!==undefined?status:out.status;
  out.status=st;
  out.campos_valores=statusTarefaCamposConclusao(out,st);
  return out;
}
function statusTarefaConclusaoEm(item){
  return item&&item.campos_valores?item.campos_valores.concluida_em||"": "";
}
function statusTarefaFmtData(data){
  if(!data)return "";
  var p=String(data).slice(0,10).split("-");
  return p.length===3?p[2]+"/"+p[1]+"/"+p[0]:data;
}
function statusTarefaOptions(selected,includeInactive){
  var rows=statusTarefaList(!!includeInactive);
  if(selected&&!rows.some(function(s){return s.id===selected;})){
    var atual=statusTarefaById(selected,true);
    if(atual)rows.push(atual);
  }
  return rows.map(function(s){return '<option value="'+s.id+'"'+(selected===s.id?' selected':'')+'>'+(s.nome||s.id)+'</option>';}).join("");
}
function statusTarefaOrdem(){
  return statusTarefaList(false).map(function(s){return s.id;});
}
function cloneEstrutura(v){
  return JSON.parse(JSON.stringify(v||[]));
}
function snapshotModeloConfig(modelo,nomePadrao,extras){
  var m=modelo||{};
  var out=Object.assign({},extras||{});
  out.nome=m.nome||nomePadrao;
  out.campos=cloneEstrutura(m.campos||[]);
  return out;
}

// Helpers compartilhados. Auth e perfil ainda ficam em app.js.
function cliNome(num){var c=clientesDB.find(function(c){return c.numero===num;});return c?c.nome:"";}
function casoDesc(num,cliNum){var cl=clientesDB.find(function(c){return c.numero===cliNum;});if(!cl)return "";var ca=casosDB.find(function(c){return c.numero===num&&c.cliente_id===cl.id;});return ca?ca.descricao:"";}
function casosDoCliente(cliNum){var cl=clientesDB.find(function(c){return c.numero===cliNum;});if(!cl)return [];return casosDB.filter(function(c){return c.cliente_id===cl.id;});}
function getFiltered(){return cards.filter(function(c){if(c.arquivado)return false;var equipeOk=!equipeAtiva||(demandaEquipesDB[c.id]||[]).includes(equipeAtiva.id);return equipeOk&&(!filterResp||respsDe(c).indexOf(filterResp)>=0)&&(!filterTipo||(c.tipos&&c.tipos.includes(filterTipo)))&&(!filterStatus||c.status===filterStatus)&&(!filterCliente||String(c.clienteNum)===String(filterCliente))&&(!filterCaso||String(c.casoNum)===String(filterCaso));}).sort(function(a,b){return (a.ordem||0)-(b.ordem||0);});}
// Capas antigas eram pastel; exibidas na versao solida equivalente (sem regravar o banco)
var COVER_SOLIDO={"#bfdbfe":"#0c66e4","#fde68a":"#946f00","#bbf7d0":"#1f845a","#e9d5ff":"#8f4fbb","#fbcfe8":"#ae4787","#fecaca":"#c9372c","#99f6e4":"#227d9b","#fed7aa":"#a54800","#c7d2fe":"#5e4db2","#d9f99d":"#5b7f24","#e2e8f0":"#626f86"};
function coverSolida(hex){var h=String(hex||"#e2e8f0").toLowerCase();return COVER_SOLIDO[h]||hex;}
function coverColor(card){return coverSolida(card.coverColor||"#e2e8f0");}
function tipoTagsHTML(tipos){if(!tipos||!tipos.length)return "";return tipos.map(function(t){var c=TC[t]||PALETA[0];return '<span style="font-size:11px;font-weight:600;padding:3px 9px;border-radius:4px;background:'+c.bg+';border:1px solid '+c.border+';color:'+c.text+';">'+t+'</span>';}).join("");}
function ccHTML(card){if(card.clienteNum&&card.casoNum)return '<span class="cc">'+card.clienteNum+'/'+card.casoNum+'</span>';if(card.clienteNum)return '<span class="cc">'+card.clienteNum+'</span>';return "";}
function buildAcList(q){if(!q||q.length<1)return [];var ql=q.toLowerCase();return clientesDB.filter(function(c){return String(c.numero).startsWith(ql)||(c.nome&&c.nome.toLowerCase().includes(ql));}).slice(0,8);}
function toolbarHTML(ce){
  var th=cards.reduce(function(s,c){return s+(c.arquivado?0:(parseFloat(c.horas)||0));},0);
  var rO=responsaveis.map(function(r){return '<option value="'+r+'"'+(filterResp===r?' selected':'')+'>'+r+'</option>';}).join("");
  var tO=TIPOS.map(function(t){return '<option value="'+t+'"'+(filterTipo===t?' selected':'')+'>'+t+'</option>';}).join("");
  var sO=COLS.map(function(c){return '<option value="'+c.id+'"'+(filterStatus===c.id?' selected':'')+'>'+c.label+'</option>';}).join("");
  var caList=filterCliente?casosDoCliente(parseInt(filterCliente)):[];
  var casoField=!filterCliente?'<input placeholder="Caso" disabled value="" style="width:72px;opacity:.4;cursor:not-allowed;"/>':caList.length>0?'<select onchange="filterCaso=this.value;renderView()" style="width:84px;"><option value="">Caso</option>'+caList.map(function(c){return '<option value="'+c.numero+'"'+(String(filterCaso)===String(c.numero)?' selected':'')+'>'+c.numero+'</option>';}).join("")+'</select>':'<input placeholder="Caso" value="'+filterCaso+'" oninput="filterCaso=this.value;renderView()" style="width:72px;" type="number" min="1"/>';
  return '<div class="toolbar"><div style="display:flex;align-items:center;gap:5px;font-size:12px;color:rgba(255,255,255,.45);">'+ic('clock')+' <span style="font-weight:700;color:rgba(255,255,255,.8);">'+th.toFixed(1)+'h</span></div><div style="display:flex;gap:5px;align-items:center;padding:4px 0;flex-wrap:wrap;"><select onchange="filterStatus=this.value;renderView()"><option value="">Status</option>'+sO+'</select><select onchange="filterTipo=this.value;renderView()"><option value="">Tipo</option>'+tO+'</select><select onchange="filterResp=this.value;renderView()"><option value="">Resp.</option>'+rO+'</select><input id="fci" placeholder="Cliente" value="'+filterCliente+'" style="width:72px;" type="number" min="1" max="9999"/>'+casoField+(viewMode==="kanban"?'<div style="display:flex;gap:3px;margin-right:3px;"><button class="view-btn '+(agruparPor==="status"?"active":"")+'" style="width:auto;padding:0 11px;font-size:11px;font-weight:600;" onclick="agruparPor=\'status\';renderKanban()">Status</button><button class="view-btn '+(agruparPor==="prazo"?"active":"")+'" style="width:auto;padding:0 11px;font-size:11px;font-weight:600;" onclick="agruparPor=\'prazo\';renderKanban()">Prazo</button></div>':"")+'<div style="display:flex;gap:3px;"><button class="view-btn '+(viewMode==="kanban"?"active":"")+'" onclick="viewMode=\'kanban\';renderView()">'+ic("kanban")+'</button><button class="view-btn '+(viewMode==="lista"?"active":"")+'" onclick="viewMode=\'lista\';renderView()">'+ic("list")+'</button></div>'+(ce?'<button class="btn btn-accent" onclick="openNew()" style="display:flex;align-items:center;gap:5px;font-size:12px;padding:5px 13px;border-radius:8px;">'+ic('plus')+' Nova demanda</button>':"")+'</div></div>';
}
function bindFCI(){var el=document.getElementById("fci");if(!el)return;el.addEventListener("change",function(){filterCliente=this.value;filterCaso="";renderView();});el.addEventListener("keydown",function(e){if(e.key==="Enter"){filterCliente=this.value;filterCaso="";renderView();}});}

